package com.gymmind.knowledge.infrastructure.search; import org.springframework.stereotype.Component; import java.util.*; @Component public class InMemoryVectorIndex implements VectorIndexPort {private final Map<String,IndexedChunk> data=new HashMap<>(); public void upsert(IndexedChunk c){if(c.vector()==null||c.vector().length!=1024)throw new IllegalArgumentException("vector dimension");data.put(c.id(),c);} public List<IndexedChunk> search(float[] v,Long t){return data.values().stream().filter(c->t.equals(c.tenantId())).sorted(Comparator.comparingDouble(c->-cos(v,c.vector()))).toList();} public void delete(String id,Long t){data.computeIfPresent(id,(k,c)->t.equals(c.tenantId())?null:c);} private static double cos(float[]a,float[]b){double x=0,y=0,z=0;for(int i=0;i<Math.min(a.length,b.length);i++){x+=a[i]*b[i];y+=a[i]*a[i];z+=b[i]*b[i];}return x/(Math.sqrt(y*z)+1e-9);}}

